<script setup>
import {computed,ref} from 'vue'
import {useRoute} from 'vue-router'
import {markets,path,fmt} from '../data'
import {session,openModal} from '../session'
import {t} from '../i18n'
import Coin from '../components/Coin.vue'
import Chart from '../components/Chart.vue'
const route=useRoute(),query=ref(''),category=ref("aiQuant.templates.filterAll"),favorites=ref([]),interval=ref("trade.interval_1h"),orderType=ref("trade.market"),leverage=ref('10'),amount=ref(''),limit=ref(''),percent=ref(0),expiry=ref('60'),records=ref("trade.futuresPositions"),error=ref('')
const mode=computed(()=>route.params.mode||'futures'),pair=computed(()=>markets.find(m=>m.id===route.params.symbol)||markets[0]),rows=computed(()=>markets.filter(m=>(category.value==="aiQuant.templates.filterAll"||category.value==="trade.marketList.favorites"&&favorites.value.includes(m.id)||m.category===category.value)&&m.name.toLowerCase().includes(query.value.toLowerCase())))
const title=computed(()=>({futures:"assets.todayPnl.futures",spot:"common.spot",options:"common.options"}[mode.value]))
function favorite(id){favorites.value=favorites.value.includes(id)?favorites.value.filter(v=>v!==id):[...favorites.value,id]}
function order(side){error.value='';if(!session.loggedIn){error.value="trade.ui.signInToTheLocalDemoFirst";return}if(!Number.isFinite(Number(amount.value))||Number(amount.value)<=0){error.value="trade.ui.enterAValidOrderAmount";return}if(orderType.value==="trade.limit"&&Number(limit.value)<=0){error.value="trade.spotErrorInvalidSizingInput";return}openModal('order',`${t(side)} · ${pair.value.name}`,{symbol:'USD',min:1,max:100000,amount:amount.value,name:`${t(title.value)} ${t(side)} ${pair.value.name}`,description:`${t(orderType.value)} · ${mode.value==='futures'?leverage.value+'x':mode.value==='options'?t('common.durationSeconds',{count:expiry.value}):t('common.spot')}`})}
</script>
<template><div class="trading-terminal"><div class="instrument-bar"><div class="coin-label"><Coin :symbol="pair.symbol"/><strong>{{ $t(pair.name) }}</strong></div><strong :class="pair.change<0?'negative':'positive'">{{ $t(fmt(pair.price)) }}</strong><span :class="pair.change<0?'negative':'positive'">{{ $t(pair.change) }}%</span><span><small>{{ $t("home.markets.colChange") }}</small>{{ $t(fmt(pair.price*.0135)) }}</span><span><small>{{ $t("trade.24hHigh") }}</small>{{ $t(fmt(pair.price*1.064)) }}</span><span><small>{{ $t("trade.24hLow") }}</small>{{ $t(fmt(pair.price*.979)) }}</span><span><small>{{ $t("home.markets.colVolume") }}</small>{{ $compact(pair.volume) }}</span><RouterLink :to="path('/copytrade')">{{ $t("auth.registerComplete.actionCopyTrade.title") }}</RouterLink></div>
<div class="terminal-grid"><aside class="terminal-panel pair-panel"><input v-model="query" :aria-label="$t(&quot;trade.searchSymbol&quot;)" :placeholder="$t(&quot;common.search&quot;)"/><nav class="trade-modes"><RouterLink v-for="(label,key) in {futures:&quot;assets.todayPnl.futures&quot;,options:&quot;common.options&quot;,spot:&quot;common.spot&quot;}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $t(label) }}</RouterLink></nav><div class="pair-categories"><button v-for="c in [&quot;trade.marketList.favorites&quot;,&quot;aiQuant.templates.filterAll&quot;,&quot;home.products.perpTag1&quot;,&quot;aiQuant.market.forex&quot;,&quot;aiQuant.market.stock&quot;]" :key="c" :class="{active:category===c}" @click="category=c">{{ $t(c) }}</button></div><div class="pair-list"><div v-for="m in rows" :key="m.id" class="pair-row"><button :aria-label="$t(favorites.includes(m.id)?'common.unfavoriteMarket':'common.favoriteMarket',{symbol:m.name})" :aria-pressed="favorites.includes(m.id)" @click="favorite(m.id)">{{ $t(favorites.includes(m.id)?'★':'☆') }}</button><RouterLink :to="path('/trade/'+mode+'/'+m.id)"><span class="coin-label"><Coin :symbol="m.symbol"/><span>{{ $t(m.name) }}<small class="mini-label">{{ $compact(m.volume) }}</small></span></span><span>{{ $t(fmt(m.price)) }}<small :class="m.change<0?'negative':'positive'">{{ $t(m.change) }}%</small></span></RouterLink></div><div v-if="!rows.length" class="empty">{{ $t("markets.ui.noMatchingMarkets") }}</div></div></aside>
<section class="terminal-panel chart-panel"><div class="timeframes"><button v-for="t in [&quot;trade.interval_1m&quot;,&quot;trade.interval_5m&quot;,&quot;trade.interval_15m&quot;,&quot;trade.interval_30m&quot;,&quot;trade.interval_1h&quot;,&quot;trade.interval_1d&quot;,&quot;trade.interval_1w&quot;,&quot;trade.interval_1M&quot;,&quot;trade.interval_1y&quot;]" :class="{active:interval===t}" @click="interval=t">{{ $t(t) }}</button><span>{{ $t("trade.ui.maIndicator") }}</span></div><Chart :price="pair.price" :interval="interval"/></section>
<section class="terminal-panel orderbook"><h2>{{ $t("trade.orderBook") }}</h2><div class="book-head"><span>{{ $t("trade.ui.priceUsd") }}</span><span>{{ $t("aiQuant.quantFund.interestRecords.table.amount") }}</span><span>{{ $t("trade.total") }}</span></div><div v-for="n in 9" :key="'ask'+n" class="book-row" :style="{'--depth':(n*7+13)+'%'}"><span class="negative">{{ $t(fmt(pair.price+(10-n)*pair.price*.00002)) }}</span><span>{{ $t((n*.0013).toFixed(4)) }}</span><span>{{ $t((n*.0037).toFixed(4)) }}</span></div><div class="book-price negative">{{ $t(fmt(pair.price)) }} ↓ <small>≈ {{ $t(fmt(pair.price)) }}{{ $t(" USD") }}</small></div><div v-for="n in 9" :key="'bid'+n" class="book-row bid" :style="{'--depth':(n*9)+'%'}"><span class="positive">{{ $t(fmt(pair.price-n*pair.price*.00002)) }}</span><span>{{ $t((n*.0017).toFixed(4)) }}</span><span>{{ $t((n*.0041).toFixed(4)) }}</span></div></section>
<section class="terminal-panel order-panel"><nav class="trade-modes"><RouterLink v-for="(label,key) in {futures:&quot;trade.futuresOrder&quot;,options:&quot;trade.optionsOrder&quot;,spot:&quot;common.spot&quot;}" :key="key" :class="{active:mode===key}" :to="path('/trade/'+key+'/'+pair.id)">{{ $t(label) }}</RouterLink></nav><div class="summary-line"><span class="mini-label">{{ $t("trade.switchToSimple") }}</span><span class="tag-chip">{{ $t(session.mode) }}{{ $t("profile.groupAccount") }}</span></div><div class="tabs"><button v-for="t in [&quot;trade.market&quot;,&quot;trade.limit&quot;]" :class="{active:orderType===t}" @click="orderType=t">{{ $t(t) }}</button></div><div v-if="mode==='futures'" class="two-cols"><label>{{ $t("trade.leverage") }}<select v-model="leverage"><option v-for="n in [1,5,10,20,50,100]" :value="String(n)">{{ $t(n) }}{{ $t("x") }}</option></select></label><label>{{ $t("trade.marginMode") }}<select :aria-label="$t(&quot;trade.marginMode&quot;)"><option :value="&quot;trade.crossed&quot;">{{ $t("trade.crossed") }}</option><option :value="&quot;trade.isolated&quot;">{{ $t("trade.isolated") }}</option></select></label></div><label v-if="mode==='options'">{{ $t("aiQuant.quantFund.positions.table.maturityDate") }}<select v-model="expiry"><option v-for="n in [60,180,300,600]" :value="String(n)">{{ $t(n) }}{{ $t("trade.ui.seconds") }}</option></select></label><label>{{ $t("trade.ui.priceUsd") }}<input v-model="limit" :disabled="orderType===&quot;trade.market&quot;" :placeholder="$t(orderType===&quot;trade.market&quot;?&quot;trade.ui.executeAtTheCurrentMarketPrice&quot;:&quot;trade.enterPrice&quot;)" inputmode="decimal"/></label><label>{{ $t("trade.ui.amountUsd") }}<input v-model="amount" inputmode="decimal" :placeholder="$t(&quot;c2c.order.fiatAmountPlaceholder&quot;)" @input="error=''"/></label><input v-model="percent" type="range" min="0" max="100" :aria-label="$t(&quot;trade.ui.percentageOfFundsToUse&quot;)" @input="amount=String(session.mode===&quot;common.demo.demo&quot;?100000*percent/100:0)"/><div class="summary-line mini-label"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><dl class="details-list"><dt>{{ $t("trade.margin") }}</dt><dd>{{ $t(fmt((Number(amount)||0)/Number(leverage))) }}{{ $t(" USD") }}</dd><dt>{{ $t("aiQuant.create.availableBalanceLabel") }}</dt><dd>{{ $t(session.mode==="common.demo.demo"?'100,000.00':'0.00') }}{{ $t(" USD") }}</dd></dl><RouterLink class="green-link" :to="path('/assets/transfer')">{{ $t("trade.ui.transfer") }}</RouterLink><p v-if="error" role="alert" class="form-error">{{ $t(error) }}</p><div class="two-cols order-buttons"><button class="buy" @click="order(mode==='spot'?&quot;assets.convert.to&quot;:&quot;trade.buyLong&quot;)">{{ $t(mode==='spot'?"assets.convert.to":"trade.buyLong") }}</button><button class="sell" @click="order(mode==='spot'?&quot;assets.convert.from&quot;:&quot;trade.sellShort&quot;)">{{ $t(mode==='spot'?"assets.convert.from":"trade.sellShort") }}</button></div><p class="mini-label">{{ $t("trade.ui.simulatedPricesAndOrdersNoTradingServiceConnected") }}</p></section></div>
<section class="terminal-panel records-panel"><div class="record-tabs"><button v-for="r in [&quot;trade.futuresPositions&quot;,&quot;trade.futuresHistory&quot;,&quot;trade.futuresOrders&quot;,&quot;trade.futuresOrdersHistory&quot;,&quot;trade.optionsOrders&quot;,&quot;trade.spotOrders&quot;,&quot;trade.spotOrdersHistory&quot;]" :class="{active:records===r}" @click="records=r">{{ $t(r) }}</button></div><div class="filter-row"><label>{{ $t("aiQuant.templates.fields.supportedSymbols") }}<select><option :value="&quot;aiQuant.templates.filterAll&quot;">{{ $t("aiQuant.templates.filterAll") }}</option><option :value="pair.name">{{ $t(pair.name) }}</option></select></label><label>{{ $t("trade.positionSide") }}<select><option :value="&quot;aiQuant.templates.filterAll&quot;">{{ $t("aiQuant.templates.filterAll") }}</option><option :value="&quot;trade.long&quot;">{{ $t("trade.long") }}</option><option :value="&quot;trade.short&quot;">{{ $t("trade.short") }}</option></select></label></div><div v-if="!session.orders.length" class="empty">{{ $t("trade.empty.positions.title") }}<p>{{ $t("trade.empty.positions.description") }}</p></div><div v-for="(o,i) in session.orders" :key="i" class="demo-order"><span>{{ $t(o.name) }}</span><span>{{ $t(o.amount) }} {{ $t(o.symbol) }}</span><span class="positive">{{ $t("withdraw.history.stages.submitted") }}</span></div></section><div class="terminal-status"><span class="positive">{{ $t("trade.ui.connectedLocalDemo") }}</span><span>{{ $t("trade.ui.marketSnapshot") }}{{ $t(pair.name) }} {{ $t(fmt(pair.price)) }}</span></div></div></template>
<style scoped>.trading-terminal{padding:0 4px 8px}.instrument-bar{display:flex;align-items:center;gap:24px;min-height:70px;padding:12px 20px;flex-wrap:wrap}.instrument-bar>strong{font-size:1.375rem}.instrument-bar small{display:block;color:#fff6;font-size:0.625rem;margin-bottom:4px}.instrument-bar>a{margin-left:auto;color:var(--nt-accent)}.terminal-grid{display:grid;grid-template-columns:21% 32% 22% 1fr;gap:4px}.terminal-panel{border:1px solid #ffffff0b;border-radius:16px;background:#080b10;min-width:0}.pair-panel{padding:12px}.pair-panel>input{width:100%;min-height:32px}.trade-modes{display:flex;gap:20px;border-bottom:1px solid #ffffff0b;padding:16px 0;font-size:0.875rem}.trade-modes .active{color:#fff;border-bottom:2px solid #fff}.trade-modes a{color:#fff6;padding-bottom:5px}.pair-categories{display:flex;gap:14px;font-size:0.75rem;padding:16px 0;flex-wrap:wrap}.pair-categories .active,.timeframes .active{color:var(--nt-accent)}.pair-categories button{color:#fff6}.pair-list{max-height:460px;overflow:auto}.pair-row{display:flex;gap:10px;padding:11px 0}.pair-row>button{color:#fff6}.pair-row>a{display:flex;justify-content:space-between;flex:1;gap:8px}.pair-row small{display:block;text-align:right;font-size:0.6875rem;margin-top:3px}.chart-panel{display:flex;flex-direction:column;overflow:hidden}.chart-panel canvas{flex:1}.timeframes{display:flex;gap:12px;flex-wrap:wrap;padding:16px 12px;font-size:0.6875rem;color:#fff7}.orderbook{padding:16px 12px}.orderbook h2{font-size:0.875rem;margin-bottom:16px}.book-head,.book-row{display:grid;grid-template-columns:1.4fr 1fr 1fr;text-align:right;font:11px 'IBM Plex Mono',monospace;padding:6px 0;position:relative}.book-row:before{content:'';position:absolute;right:0;top:0;bottom:0;width:var(--depth);background:#e34a6810;pointer-events:none}.book-row.bid:before{background:#5bbb9110}.book-head{color:#fff6;font:10px 'Exo 2',sans-serif}.book-head>span:first-child,.book-row>span:first-child{text-align:left}.book-price{font-size:1.5rem;padding:20px 0}.book-price small{display:block;font-size:0.6875rem;color:#fff6;margin-top:4px}.order-panel{padding:0 16px 20px;display:grid;gap:16px}.order-panel label{font-size:0.75rem;color:#fff8}.order-panel .two-cols{gap:8px}.order-panel .details-list{margin:0;font-size:0.6875rem}.order-panel .tabs button{border:0;border-radius:24px;padding:6px 16px;background:#ffffff08}.order-buttons button{padding:12px 5px;border-radius:8px;color:#fff;font-size:0.75rem}.buy{background:#2b8e65}.sell{background:#b53951}.records-panel{margin-top:4px}.records-panel .filter-row{margin:16px}.demo-order{padding:16px;display:flex;justify-content:space-between;gap:16px;border-top:1px solid #ffffff0b}.terminal-status{display:flex;justify-content:space-between;font-size:0.6875rem;padding:12px 8px;color:#fff7}@media(max-width:1150px){.terminal-grid{grid-template-columns:23% 1fr 30%}.orderbook{grid-column:1;grid-row:2}.order-panel{grid-column:3;grid-row:1/3}.chart-panel{grid-column:2;grid-row:1/3}.pair-panel{grid-column:1}.pair-list{max-height:260px}.instrument-bar{gap:16px}}@media(max-width:750px){.terminal-grid{grid-template-columns:1fr 1fr}.chart-panel{grid-column:1/3;grid-row:1;height:380px}.order-panel{grid-column:1/3;grid-row:2}.pair-panel{grid-column:1;grid-row:3}.orderbook{grid-column:2;grid-row:3}.instrument-bar{padding:12px;gap:14px;font-size:0.6875rem}.instrument-bar .coin-label{font-size:1rem}.instrument-bar>strong{font-size:1.125rem}.instrument-bar>a{margin-left:0}.pair-row{font-size:0.6875rem}.pair-categories{gap:8px}.trade-modes{gap:12px}.pair-list{max-height:440px}.book-row{font-size:0.5625rem}.book-price{font-size:1.125rem}.book-head{font-size:0.5625rem}.terminal-status{gap:16px}.records-panel .record-tabs{gap:14px;font-size:0.75rem}.demo-order{font-size:0.75rem;flex-wrap:wrap}}
@media(min-width:1151px){.trading-terminal{display:grid;grid-template-columns:21% 32% 22% 1fr;grid-template-rows:64px 500px minmax(280px,1fr) auto;gap:4px;min-height:calc(100dvh - 64px)}.terminal-grid{display:contents}.instrument-bar{grid-column:1/3;grid-row:1;gap:12px;padding:10px 12px;min-height:0;font-size:0.6875rem}.instrument-bar>strong{font-size:1.125rem}.instrument-bar .coin{width:28px;height:28px}.instrument-bar .coin-label{font-size:1rem}.instrument-bar small{font-size:0.5625rem}.instrument-bar>a{font-size:0.625rem}.pair-panel{grid-column:1;grid-row:2;padding:12px}.chart-panel{grid-column:2;grid-row:2}.orderbook{grid-column:3;grid-row:1/3}.order-panel{grid-column:4;grid-row:1/3;gap:10px;align-content:start;font-size:0.75rem}.order-panel .trade-modes{padding:12px 0;font-size:0.75rem}.order-panel .two-cols{grid-template-columns:1fr}.order-panel .order-buttons{grid-template-columns:1fr 1fr}.order-panel input,.order-panel select{min-height:32px;padding:7px 12px}.order-panel label{gap:4px}.order-panel .tabs button{flex:1;border-radius:4px}.order-panel .tabs button.active{background:#5bbb91;color:#fff}.order-panel .summary-line{font-size:0.625rem}.order-panel .details-list{gap:10px}.order-panel .tag-chip{padding:2px 8px}.order-panel .mini-label{font-size:0.625rem}.order-panel input[type=range]{min-height:16px;padding:0}.records-panel{grid-column:1/-1;grid-row:3;margin:0}.records-panel .record-tabs{font-size:0.75rem;padding:8px 16px;gap:16px}.records-panel .filter-row{font-size:0.6875rem;margin:10px 16px}.records-panel select{min-height:24px;font-size:0.6875rem;padding:3px 8px;background:transparent}.records-panel .empty{padding:60px 20px}.terminal-status{grid-column:1/-1;grid-row:4}.pair-list{max-height:370px}.pair-row{font-size:0.75rem;padding:7px 0}.pair-row .coin{width:26px;height:26px}.pair-row .coin-label{font-size:0.75rem;gap:7px}.pair-row small{text-align:left;font-size:0.625rem}.pair-row>a>span:last-child small{text-align:right}.pair-categories{gap:12px;padding:12px 0;font-size:0.6875rem}.trade-modes{padding:12px 0;font-size:0.75rem}.book-row{padding:5px 0;font-size:0.6875rem}.book-price{padding:18px 0}.book-head{font-size:0.625rem}.orderbook h2{margin-bottom:12px}.orderbook{padding:16px 12px}}
</style>
